import { getUserContext } from '@/lib/supabase/user-context'
import { createClient } from '@/lib/supabase/server'
import { PortalHeader, PortalTable, EmptyState, StatusPill, formatDate, money, StatCard } from '@/components/portal/portal-shell'

export default async function PortalFeesPage() { const context = await getUserContext(); const supabase = await createClient(); const { data: profile } = await supabase.from('profiles').select('student_id').eq('id', context!.userId).maybeSingle(); const { data: links } = await supabase.from('parent_student_links').select('student_id').eq('parent_profile_id', context!.userId); const ids = [...new Set([...(links ?? []).map((x) => x.student_id), ...(profile?.student_id ? [profile.student_id] : [])])]; const { data: fees } = ids.length ? await supabase.from('student_fees').select('id,amount,status,due_date').in('student_id', ids).order('due_date') : { data: [] as any[] }; const feeIds = (fees ?? []).map((f) => f.id); const { data: payments } = feeIds.length ? await supabase.from('payments').select('student_fee_id,amount,payment_date').in('student_fee_id', feeIds).order('payment_date', { ascending: false }) : { data: [] as any[] }; const paid = (payments ?? []).reduce((sum, p) => sum + Number(p.amount), 0); const total = (fees ?? []).reduce((sum, f) => sum + Number(f.amount), 0); return <><PortalHeader title="Fees" description="Read-only fee balances and payment history." /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Total fee" value={money(total)} /><StatCard label="Amount paid" value={money(paid)} /><StatCard label="Remaining" value={money(Math.max(total - paid, 0))} /></div><div className="mt-6 space-y-6">{fees?.length ? <><PortalTable headers={['Fee', 'Due date', 'Status', 'Amount']} rows={fees.map((fee) => [fee.id.slice(0, 8), formatDate(fee.due_date), <StatusPill key={fee.id}>{fee.status}</StatusPill>, money(Number(fee.amount))])} /><section><h2 className="mb-3 font-display text-lg font-semibold">Payment history</h2>{payments?.length ? <PortalTable headers={['Date', 'Amount', 'Fee']} rows={payments.map((payment) => [formatDate(payment.payment_date), money(Number(payment.amount)), payment.student_fee_id.slice(0, 8)])} /> : <EmptyState text="No payments recorded yet." />}</section></> : <EmptyState text="No fee records are available." />}</div></> }
